using GarageManager.DAL;namespace GarageManager.BUS;public sealed class GarageService{public GarageRepository Repository {get;}=new();public void ValidateCustomer(string name,string phone){if(string.IsNullOrWhiteSpace(name)||string.IsNullOrWhiteSpace(phone))throw new InvalidOperationException("Nhập tên chủ xe và số điện thoại.");}public void ValidateVehicle(string plate,string make){if(string.IsNullOrWhiteSpace(plate)||string.IsNullOrWhiteSpace(make))throw new InvalidOperationException("Nhập biển số và hiệu xe.");}}